from batch07 import *
start('etherchannel','EtherChannel — członkowie i awarie','2.4',['https://www.cisco.com/c/en/us/td/docs/switches/lan/c9000/lyr2-fwd/etherchannel/etherchannel-configuration-guide/m_ethernetchannel.html'],True)
q('Lokalny numer grupy','SW1 używa channel-group 1, a SW2 channel-group 7. Pozostałe parametry LACP są zgodne. Czy sama różnica numerów musi blokować agregację?','Nie, numery grup są lokalne',['Tak, numer zawsze musi być identyczny po obu stronach|Lokalny identyfikator Port-channel nie jest obowiązkowo wspólny.','Tak, tylko grupa 1 obsługuje LACP|Inne numery mogą obsługiwać LACP.','Nie, bo LACP w ogóle nie sprawdza partnera|LACP negocjuje parametry i partnera, tylko nie wymaga tej samej lokalnej numeracji.'],'Numer lokalnej grupy odróżnia interfejsy logiczne na urządzeniu, nie jest uniwersalnym ID obu końców.')
q('Active plus passive','Czy para LACP active/passive może utworzyć agregację przy zgodnych pozostałych ustawieniach?','Tak',['Nie, wymagane zawsze active/active|Jedna strona active może zainicjować negocjację.','Nie, passive oznacza shutdown|Passive nie jest wyłączeniem portu.','Tak, ale to PAgP|Active/passive należą do LACP.'],'Co najmniej jedna strona musi inicjować wymianę LACP.')
c('Od pasywnego do aktywnego','W labie G1/0/1 ma należeć do LACP 8 jako active. Uzupełnij numer grupy i tryb; zgodność konfiguracji oraz możliwość zmiany trybu sprawdzono.','SW(config-if)# channel-group {{b0}} mode {{b1}}',['8','active'],'Active inicjuje negocjację; nie naprawia automatycznie pozostałych niezgodności członków.')
q('LACP a PAgP','Na jednej stronie mode desirable, na drugiej mode active. Co jest niezgodne?','Użyto różnych protokołów negocjacji',['Wyłącznie liczba liter w hostname|Nie jest parametrem negocjacji.','Oba końce są LACP passive|Desirable należy do PAgP, active do LACP.','Zawsze tylko maska IPv4|Problem wskazany dotyczy agregacji L2.'],'Tryby desirable/auto to PAgP, active/passive to LACP; trzeba uzgodnić protokół.')
c('Dwa członki access','Zakres G1/0/1–2 jest już statycznym access o zgodnych parametrach. Przypisz VLAN 30 i LACP grupę 3 w trybie active.','SW(config-if-range)# switchport access vlan {{b0}}\nSW(config-if-range)# channel-group {{b1}} mode active',['30','3'],'Członkowie muszą mieć spójną konfigurację VLAN i agregacji.')
q('Statyczne on','Jakie ryzyko niesie mode on przy niespójnej konfiguracji drugiego końca?','Brak negocjacji może nie wykryć błędnego połączenia tak jak protokół agregacji',['On zawsze szyfruje ramki|To nie funkcja szyfrowania.','On automatycznie uruchamia LACP|On oznacza agregację statyczną.','On wymusza jeden identyczny kabel|Nie oznacza tego rodzaju ograniczenia.'],'Agregacja statyczna wymaga szczególnie starannej zgodności obu końców i okablowania.')
q('STP i wiązka','Jak STP zwykle traktuje prawidłowo utworzony EtherChannel L2?','Jako jeden logiczny port',['Zawsze jako pętlę wymagającą wyłączenia wszystkich członków|Poprawny kanał jest traktowany logicznie jako jedno łącze.','Jak router wykonujący NAT|To nie funkcja STP.','Jako osobny VLAN dla każdego kabla|EtherChannel nie wymusza takiego podziału.'],'Agregacja pozwala wykorzystać wiele fizycznych łączy jako jedną ścieżkę logiczną dla STP.')
q('Awaria jednego członka','Dwa aktywne łącza LACP działają w jednej wiązce. Jedno pada; nie ma ograniczenia min-links wymagającego dwóch. Co jest oczekiwane?','Kanał może działać na pozostałym łączu z mniejszą przepustowością',['Zawsze musi całkowicie zniknąć|Podane założenie nie wymaga dwóch aktywnych członków.','Przepustowość pozostałego kabla podwaja się fizycznie|Nie zmienia się szybkość sprzętowa portu.','Numer Port-channel musi zmienić się automatycznie|Nie jest to konieczny skutek awarii.'],'Odporność zależy od stanu reszty wiązki i polityk platformy, nie tylko liczby skonfigurowanych portów.')
c('Trunk logiczny','Na istniejącym Port-channel3 ustaw trunk, native VLAN 99 i listę allowed 10,20,99. Zgodność członków i drugiego końca została zaplanowana.','SW(config)# interface Port-channel3\nSW(config-if)# switchport mode {{b0}}\nSW(config-if)# switchport trunk native vlan {{b1}}\nSW(config-if)# switchport trunk allowed vlan {{b2}}',['trunk','99','10,20,99'],'Parametry logicznej wiązki należy weryfikować również na członkach zgodnie z platformą.')
q('Nierówny rozkład','Dwa członki EtherChannel przenoszą różne ilości danych. Czy to zawsze świadczy o błędzie?','Nie, wynik zależy od algorytmu haszowania i zestawu przepływów',['Tak, każdy bajt musi być idealnie podzielony po równo|Hash nie gwarantuje równego podziału bajtów.','Tak, oba porty zawsze mają identyczne liczniki|Licznik zależy od przypisanych przepływów.','Nie, bo drugi port nigdy nie jest używany|Wiele przepływów może korzystać z wielu członków.'],'Hash zwykle zachowuje kolejność danego przepływu, a nie wyrównuje każdą chwilową liczbę bajtów.')
c('Sprawdź wiązkę warstwami','Pokaż skrót EtherChannel, sąsiadów LACP i stan trunków.','SW# show etherchannel {{b0}}\nSW# show lacp {{b1}}\nSW# show interfaces {{b2}}',['summary','neighbor','trunk'],'Zestawienie stanu wiązki, partnera i VLAN-ów pozwala zawęzić różne klasy problemów.')
q('Nie ten partner','Dwa kable planowane do jednej wiązki kończą się na niezależnych switchach bez wspólnej funkcji wielochassis. Czy można założyć zwykłą poprawną agregację?','Nie, należy zapewnić właściwą wspólną logiczną stronę agregacji',['Tak, wystarczy ten sam kolor kabli|Kolor nie tworzy wspólnego partnera.','Tak, jeśli oba switche mają taki sam hostname|Hostname nie czyni ich jednym partnerem LACP.','Tak, numery portów są zawsze globalnym identyfikatorem|Numery są lokalne.'],'Port-channel wymaga zgodnego partnera logicznego; rozwiązania wielochassis mają własne wymagania.')
q('Stan suspended','Członek widnieje jako suspended. Co należy zrobić przed przyjęciem, że przenosi ruch w wiązce?','Sprawdzić przyczynę zawieszenia, zgodność i negocjację',['Doliczyć jego pełne pasmo do dostępnego|Skonfigurowany port nie musi być operacyjnym członkiem.','Usunąć wszystkie pozostałe porty|To nie celowana diagnoza.','Uznać, że suspended oznacza idealny stan|Nazwa wskazuje stan wymagający interpretacji.'],'Oceniaj stan operacyjny oraz legendę konkretnego outputu, nie tylko obecność konfiguracji.')
q('Różna lista VLAN','Jeden członek ma inną listę allowed niż reszta. Co należy zweryfikować?','Spójność konfiguracji członków i Port-channel',['Tylko hasło użytkownika SSH|Nie naprawia parametrów trunku.','Wyłącznie DNS telefonu|Nie jest wskazaną przyczyną agregacji.','Czy klient ma tyle RAM co switch|To nie wymaganie EtherChannel.'],'Niespójne parametry warstwy drugiej mogą uniemożliwiać prawidłowe włączenie członka.')
c('Rozszerz bez nadpisania','Na Port-channel4 dodaj VLAN 70 do allowed bez usuwania innych, pokaż skrót wiązek i trunki.','SW(config-if)# switchport trunk allowed vlan {{b0}} 70\nSW(config-if)# end\nSW# show etherchannel {{b1}}\nSW# show interfaces {{b2}}',['add','summary','trunk'],'Zmiana powinna obejmować uzgodniony transport na obu końcach; komenda add chroni dotychczasową listę.')
q('Konfiguracja a operacyjność','Running-config pokazuje channel-group na dwóch portach, ale summary tylko jeden bundled. Ile aktywnych członków można potwierdzić tym wynikiem?','Jeden',['Dwa, bo konfiguracja zawsze oznacza działanie|Stan administracyjny nie gwarantuje operacyjnego.','Zero, bo wiązka wymaga zawsze czterech portów|Nie ma takiego ogólnego wymogu.','Nieograniczoną liczbę|Liczba członków jest konkretna i ograniczona.'],'Dostępną przepustowość oceniaj na podstawie faktycznie dołączonych portów.')
c('Kontrola po awarii','Po utracie członka sprawdź summary, sąsiadów LACP oraz STP VLAN 80.','SW# show etherchannel {{b0}}\nSW# show lacp {{b1}}\nSW# show spanning-tree vlan {{b2}}',['summary','neighbor','80'],'Po awarii trzeba potwierdzić zarówno wiązkę, jak i logiczną ścieżkę L2.')
q('Haszowanie a test','Jeden test TCP nie wykorzystuje sumy przepustowości czterech członków. Jaki test lepiej bada agregat?','Wiele niezależnych przepływów z uwzględnieniem pól używanych przez hash',['Wyłącznie ten sam pojedynczy przepływ dłużej|Może nadal trafiać na ten sam członek.','Ping z identycznymi parametrami raz dziennie|Nie mierzy sumarycznej przepustowości wiązki.','Zmiana numeru Port-channel bez pomiarów|Numer logiczny nie gwarantuje innego rozkładu.'],'Pomiar musi uwzględniać algorytm rozdziału, liczbę przepływów i ograniczenia końców testu.')
end()
